import { createContext, useContext, useEffect, useMemo, useState } from 'react'
import { BrowserRouter, NavLink, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import {
  Alert, AppBar, Avatar, Badge, Box, Button, Card, CardContent, Chip, CircularProgress, Dialog, DialogActions,
  DialogContent, DialogTitle, Divider, Drawer, FormControl, IconButton, InputAdornment, LinearProgress, MenuItem,
  Select, Snackbar, Stack, Tab, Tabs, TextField, Toolbar, Tooltip, Typography, useMediaQuery, useTheme,
} from '@mui/material'
import { DataGrid } from '@mui/x-data-grid'
import { BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis, Bar } from 'recharts'
import DashboardRounded from '@mui/icons-material/DashboardRounded'
import GroupsRounded from '@mui/icons-material/GroupsRounded'
import EventAvailableRounded from '@mui/icons-material/EventAvailableRounded'
import CalendarMonthRounded from '@mui/icons-material/CalendarMonthRounded'
import ApartmentRounded from '@mui/icons-material/ApartmentRounded'
import AssessmentRounded from '@mui/icons-material/AssessmentRounded'
import AccessTimeRounded from '@mui/icons-material/AccessTimeRounded'
import MenuRounded from '@mui/icons-material/MenuRounded'
import AddRounded from '@mui/icons-material/AddRounded'
import SearchRounded from '@mui/icons-material/SearchRounded'
import NotificationsNoneRounded from '@mui/icons-material/NotificationsNoneRounded'
import ArrowBackRounded from '@mui/icons-material/ArrowBackRounded'
import ArrowForwardRounded from '@mui/icons-material/ArrowForwardRounded'
import EditRounded from '@mui/icons-material/EditRounded'
import DeleteOutlineRounded from '@mui/icons-material/DeleteOutlineRounded'
import MoreHorizRounded from '@mui/icons-material/MoreHorizRounded'
import DownloadRounded from '@mui/icons-material/DownloadRounded'
import PrintRounded from '@mui/icons-material/PrintRounded'
import ArrowUpwardRounded from '@mui/icons-material/ArrowUpwardRounded'
import ArrowDownwardRounded from '@mui/icons-material/ArrowDownwardRounded'
import { seedAttendance, seedDepartments, seedEmployees, seedSettings } from './data/mockData'
import { attendancePercent, calculateMinutesLate, calculateWorkingHours, localDate, monthKey, monthWeekdays, recordsFor, statusForToday, summarize } from './utils/attendance'
import { loadData, saveData } from './utils/storage'
import { downloadCsv } from './utils/csv'

const Store = createContext(null)
const useStore = () => useContext(Store)
const NAV = [
  { label: 'Workspace', links: [{ label: 'Overview', path: '/', Icon: DashboardRounded }, { label: 'Employees', path: '/employees', Icon: GroupsRounded }, { label: 'Attendance', path: '/attendance', Icon: EventAvailableRounded }, { label: 'Calendar', path: '/calendar', Icon: CalendarMonthRounded }, { label: 'Monthly report', path: '/monthly', Icon: AssessmentRounded }, { label: 'Departments', path: '/departments', Icon: ApartmentRounded }, { label: 'Reports', path: '/reports', Icon: AssessmentRounded }] },
]
const today = localDate()
const statusColor = status => ({ Present: 'success', Late: 'warning', Absent: 'error', 'On Leave': 'info', 'Not Marked': 'default', Active: 'success', Inactive: 'default' }[status] || 'default')
const prettyDate = date => date ? new Date(`${date}T12:00:00`).toLocaleDateString('en-ZA', { day: 'numeric', month: 'short', year: 'numeric' }) : '—'
const monthLabel = month => month ? new Date(`${month}-02T12:00:00`).toLocaleDateString('en-ZA', { month: 'long', year: 'numeric' }) : ''

function App() {
  const [employees, setEmployees] = useState(() => loadData('employees', seedEmployees))
  const [departments, setDepartments] = useState(() => loadData('departments', seedDepartments))
  const [records, setRecords] = useState(() => loadData('attendanceRecords', seedAttendance))
  const [settings, setSettings] = useState(() => loadData('applicationSettings', seedSettings))
  const [loading, setLoading] = useState(true)
  const [toast, setToast] = useState(null)
  useEffect(() => { const timer = window.setTimeout(() => setLoading(false), 350); return () => window.clearTimeout(timer) }, [])
  useEffect(() => saveData('employees', employees), [employees])
  useEffect(() => saveData('departments', departments), [departments])
  useEffect(() => saveData('attendanceRecords', records), [records])
  useEffect(() => saveData('applicationSettings', settings), [settings])
  const value = { employees, setEmployees, departments, setDepartments, records, setRecords, settings, setSettings, loading, notify: (message, severity = 'success') => setToast({ message, severity }) }
  return <Store.Provider value={value}><BrowserRouter><Shell/><Snackbar open={Boolean(toast)} autoHideDuration={3500} onClose={() => setToast(null)} anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}><Alert onClose={() => setToast(null)} severity={toast?.severity} variant="filled">{toast?.message}</Alert></Snackbar></BrowserRouter></Store.Provider>
}

function Shell() {
  const [mobileOpen, setMobileOpen] = useState(false)
  const theme = useTheme()
  const mobile = useMediaQuery(theme.breakpoints.down('md'))
  const location = useLocation()
  const { records } = useStore()
  const activeLate = records.filter(r => r.date === today && r.status === 'Late').length
  const drawer = <Box className="sidebar-inner">
    <Box className="brand"><Box className="brand-mark">c</Box><Box><Typography fontWeight={750} fontSize={17} lineHeight={1.1}>cielo</Typography><Typography variant="caption" color="text.secondary">PEOPLE OPERATIONS</Typography></Box></Box>
    {NAV.map(group => <Box key={group.label} className="nav-group"><Typography className="nav-caption">{group.label}</Typography>{group.links.map(({ label, path, Icon }) => <NavLink end={path === '/'} to={path} key={path} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`} onClick={() => setMobileOpen(false)}><Icon fontSize="small"/><span>{label}</span>{label === 'Attendance' && activeLate > 0 && <Badge color="warning" badgeContent={activeLate} max={9}/>}</NavLink>)}</Box>)}
    <Box className="sidebar-bottom"><Divider/><Box className="profile"><Avatar sx={{ bgcolor: '#e8d9ce', color: '#684d3e', width: 36, height: 36 }}>AM</Avatar><Box flex={1}><Typography variant="body2" fontWeight={650}>Alex Morgan</Typography><Typography variant="caption" color="text.secondary">Administrator</Typography></Box><MoreHorizRounded fontSize="small" color="action"/></Box></Box>
  </Box>
  const title = [...NAV[0].links].find(item => item.path === location.pathname)?.label || (location.pathname.startsWith('/employees/') ? 'Employee profile' : 'Monthly report')
  return <Box className="app-frame"><Box component="nav" className="sidebar">{drawer}</Box><Drawer open={mobileOpen} onClose={() => setMobileOpen(false)} sx={{ '& .MuiDrawer-paper': { width: 250 } }}>{drawer}</Drawer>
    <Box className="main-frame"><AppBar className="topbar" position="sticky" elevation={0}><Toolbar><IconButton onClick={() => setMobileOpen(true)} sx={{ display: { md: 'none' }, mr: 1 }}><MenuRounded/></IconButton><Typography variant="body2" color="text.secondary" className="crumb">Workspace <span>/</span> <b>{title}</b></Typography><Box flex={1}/><Chip size="small" label={new Date().toLocaleDateString('en-ZA', { weekday: 'short', day: 'numeric', month: 'short' })} variant="outlined" className="date-chip"/><Tooltip title={`${activeLate} late arrivals today`}><IconButton sx={{ ml: 1 }}><Badge badgeContent={activeLate} color="warning"><NotificationsNoneRounded/></Badge></IconButton></Tooltip><Avatar sx={{ bgcolor: '#dce8e1', color: '#356859', width: 34, height: 34, ml: 1, fontSize: 13 }}>AM</Avatar></Toolbar></AppBar>
      <Box component="main" className="page-content"><Routes><Route path="/" element={<Dashboard/>}/><Route path="/employees" element={<EmployeesPage/>}/><Route path="/employees/:employeeId" element={<EmployeeDetails/>}/><Route path="/attendance" element={<AttendancePage/>}/><Route path="/calendar" element={<CalendarPage/>}/><Route path="/monthly" element={<MonthlyPage/>}/><Route path="/departments" element={<DepartmentsPage/>}/><Route path="/reports" element={<ReportsPage/>}/><Route path="*" element={<Dashboard/>}/></Routes></Box>
    </Box></Box>
}

function PageHeader({ eyebrow, title, subtitle, action }) { return <Box className="page-header"><Box><Typography className="eyebrow">{eyebrow}</Typography><Typography variant="h4" className="page-title">{title}</Typography>{subtitle && <Typography color="text.secondary" mt={.7}>{subtitle}</Typography>}</Box>{action}</Box> }
function StatCard({ title, value, note, Icon, color = '#356859', trend, progress }) { return <Card className="stat-card"><CardContent><Box display="flex" justifyContent="space-between" alignItems="flex-start"><Box><Typography variant="body2" color="text.secondary">{title}</Typography><Typography className="stat-value">{value}</Typography></Box><Box className="stat-icon" sx={{ color, bgcolor: `${color}12` }}><Icon fontSize="small"/></Box></Box><Box display="flex" alignItems="center" gap={.5} mt={1.2}>{trend && <Typography variant="caption" color="success.main" fontWeight={700}>{trend}</Typography>}<Typography variant="caption" color="text.secondary">{note}</Typography></Box>{progress !== undefined && <LinearProgress variant="determinate" value={progress} sx={{ mt: 1.2, height: 5, borderRadius: 4 }}/>}</CardContent></Card> }
function Status({ value }) { return <Chip size="small" label={value} color={statusColor(value)} variant={value === 'Not Marked' ? 'outlined' : 'filled'} className="status-chip"/> }
function Panel({ title, action, children, className = '' }) { return <Card className={`panel ${className}`}><Box className="panel-heading"><Typography variant="h6">{title}</Typography>{action}</Box>{children}</Card> }
function GridTable({ rows, columns, onRowClick }) { const { loading } = useStore(); return <Box className="data-grid-wrap"><DataGrid rows={rows} columns={columns} loading={loading} slots={{ loadingOverlay: () => <Box sx={{ display: 'grid', placeItems: 'center', height: '100%' }}><CircularProgress size={25}/></Box> }} autoHeight disableRowSelectionOnClick pageSizeOptions={[8, 15, 25]} initialState={{ pagination: { paginationModel: { pageSize: 8 } } }} onRowClick={onRowClick} sx={{ border: 0, '& .MuiDataGrid-columnHeaders': { bgcolor: '#f8f9f8', borderBottom: '1px solid #edf0ee' }, '& .MuiDataGrid-columnHeaderTitle': { fontWeight: 650, fontSize: 12, color: '#68716d' }, '& .MuiDataGrid-cell': { borderColor: '#f0f1f0', fontSize: 13 }, '& .MuiDataGrid-footerContainer': { borderColor: '#edf0ee' } }}/></Box> }
function useAttendanceStats() {
  const { employees, records, departments, settings } = useStore()
  return useMemo(() => {
    const todays = records.filter(r => r.date === today)
    const counts = summarize(todays)
    const eligible = employees.filter(e => e.status === 'Active')
    return { todays, counts, eligible, present: counts.Present || 0, unmarked: Math.max(0, eligible.length - todays.length), percent: attendancePercent(todays, eligible.length), lateRecords: records.filter(r => r.status === 'Late'), settings }
  }, [employees, records, departments, settings])
}
function Dashboard() {
  const { employees, records, departments, settings } = useStore()
  const stats = useAttendanceStats()
  const deptRows = departments.map((dept, i) => {
    const members = employees.filter(e => e.department === dept.name && e.status === 'Active')
    const todayRows = stats.todays.filter(r => members.some(e => e.id === r.employeeId))
    return { id: dept.id, name: dept.name, headcount: members.length, percent: attendancePercent(todayRows, members.length), delta: `${i % 2 ? '+' : '+'}${(2 + i % 5)}%` }
  })
  const deptBars = deptRows.map(d => ({ name: d.name.split(' ')[0], attendance: d.percent }))
  const pie = [{ name: 'Present', value: stats.present, color: '#4b9478' }, { name: 'Absent', value: stats.counts.Absent || 0, color: '#e07970' }]
  const recent = [...records].sort((a, b) => b.date.localeCompare(a.date) || b.id.localeCompare(a.id)).slice(0, 6)
  const peopleById = Object.fromEntries(employees.map(e => [e.id, e]))
  const cols = [{ field: 'employee', headerName: 'EMPLOYEE', flex: 1.3, minWidth: 165, renderCell: p => <Box className="employee-cell"><Avatar className="table-avatar">{p.row.employee?.split(' ').map(x => x[0]).slice(0, 2).join('')}</Avatar><Box><Typography variant="body2" fontWeight={650}>{p.row.employee}</Typography><Typography variant="caption" color="text.secondary">{p.row.department}</Typography></Box></Box> }, { field: 'date', headerName: 'DATE', width: 120, valueFormatter: value => prettyDate(value) }, { field: 'checkIn', headerName: 'CHECK IN', width: 105, renderCell: p => p.value || '—' }, { field: 'status', headerName: 'STATUS', width: 120, renderCell: p => <Status value={p.value}/> }]
  const lateToday = stats.todays.filter(r => r.status === 'Late').slice(0, 4)
  return <><PageHeader eyebrow={new Date().toLocaleDateString('en-ZA', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).toUpperCase()} title="Good morning, Alex" subtitle="Here’s what’s happening across your team today." action={<Button variant="contained" startIcon={<AddRounded/>} component={NavLink} to="/attendance">Record attendance</Button>}/>
    <Box className="stats-grid"><StatCard title="Total employees" value={employees.filter(e => e.status === 'Active').length} note="Across all departments" Icon={GroupsRounded}/><StatCard title="Present today" value={stats.present} note={`${stats.percent}% attendance rate`} Icon={EventAvailableRounded} color="#468e71"/><StatCard title="Absent today" value={stats.counts.Absent || 0} note="Needs follow-up" Icon={ArrowDownwardRounded} color="#d56c64"/><StatCard title="Late today" value={stats.counts.Late || 0} note={`After ${settings.expectedStart}`} Icon={AccessTimeRounded} color="#d58a35"/><StatCard title="Attendance rate" value={`${stats.percent}%`} note="Present / active employees" Icon={AssessmentRounded} color="#468e71"/><StatCard title="Departments" value={departments.length} note="Active teams" Icon={ApartmentRounded} color="#7186bb"/><StatCard title="On leave" value={stats.counts['On Leave'] || 0} note="Approved leave" Icon={CalendarMonthRounded} color="#7186bb"/><StatCard title="Unmarked" value={stats.unmarked} note="Awaiting check-in" Icon={MoreHorizRounded} color="#8a9390"/></Box>
    <Box className="dashboard-grid"><Panel title="Attendance overview" action={<Select size="small" defaultValue="week" className="tiny-select"><MenuItem value="week">This week</MenuItem><MenuItem value="month">This month</MenuItem></Select>}><CardContent className="chart-card"><Box className="chart-kpi"><Typography variant="h3">{stats.percent}%</Typography><Chip size="small" color="success" label="Today"/><Typography variant="caption" color="text.secondary">Present or late arrivals</Typography></Box><Box height={190}><ResponsiveContainer width="100%" height="100%"><BarChart data={weekTrend(records, employees)} margin={{ top: 8, right: 8, left: -25, bottom: 0 }}><CartesianGrid vertical={false} stroke="#edf0ee"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#88928d', fontSize: 11 }}/><YAxis domain={[0, 100]} axisLine={false} tickLine={false} tick={{ fill: '#88928d', fontSize: 11 }} tickFormatter={v => `${v}%`}/><ChartTooltip formatter={v => [`${v}%`, 'Attendance']}/><Bar dataKey="rate" fill="#4d9279" radius={[5, 5, 0, 0]} barSize={24}/></BarChart></ResponsiveContainer></Box></CardContent></Panel>
      <Panel title="Present vs absent" action={<IconButton size="small"><MoreHorizRounded/></IconButton>}><CardContent className="donut-content"><Box height={170} width="58%"><ResponsiveContainer><PieChart><Pie data={pie} dataKey="value" nameKey="name" innerRadius={52} outerRadius={74} paddingAngle={4} stroke="none">{pie.map(x => <Cell key={x.name} fill={x.color}/>)}</Pie><ChartTooltip/></PieChart></ResponsiveContainer><Box className="donut-center"><b>{stats.present + (stats.counts.Absent || 0)}</b><small>marked</small></Box></Box><Stack gap={1.5} flex={1}>{pie.map(x => <Box key={x.name} display="flex" alignItems="center" gap={1}><span className="legend-dot" style={{ background: x.color }}/><Box flex={1}><Typography variant="caption" color="text.secondary">{x.name}</Typography><Typography fontWeight={700} fontSize={17}>{x.value}</Typography></Box></Box>)}</Stack></CardContent></Panel>
      <Panel title="Department attendance" action={<Button size="small" component={NavLink} to="/departments">View all</Button>} className="wide-panel"><CardContent sx={{ height: 230 }}><ResponsiveContainer><BarChart data={deptBars} margin={{ top: 8, right: 8, left: -25, bottom: 0 }}><CartesianGrid vertical={false} stroke="#edf0ee"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#88928d', fontSize: 11 }}/><YAxis domain={[0, 100]} axisLine={false} tickLine={false} tick={{ fill: '#88928d', fontSize: 11 }} tickFormatter={v => `${v}%`}/><ChartTooltip formatter={v => [`${v}%`, 'Attendance']}/><Bar dataKey="attendance" fill="#7aac96" radius={[5, 5, 0, 0]} barSize={35}/></BarChart></ResponsiveContainer></CardContent></Panel>
      <Panel title="Late arrivals" action={<Button size="small" component={NavLink} to="/attendance">See attendance</Button>} className="late-panel"><CardContent className="late-list">{lateToday.length ? lateToday.map(r => { const e = peopleById[r.employeeId]; return <Box className="late-row" key={r.id}><Avatar className="table-avatar">{e?.name.split(' ').map(n => n[0]).slice(0, 2).join('')}</Avatar><Box flex={1}><Typography variant="body2" fontWeight={650}>{e?.name || 'Employee'}</Typography><Typography variant="caption" color="text.secondary">{e?.department}</Typography></Box><Box textAlign="right"><Typography variant="body2" fontWeight={650}>{r.checkIn}</Typography><Typography variant="caption" color="warning.main">+{calculateMinutesLate(r.checkIn, settings.expectedStart)} min</Typography></Box></Box> }) : <Empty label="No late arrivals recorded today"/>}</CardContent></Panel>
      <Panel title="Absent today" action={<Button size="small" component={NavLink} to="/reports">View report</Button>} className="late-panel"><CardContent className="late-list">{stats.todays.filter(r => r.status === 'Absent').slice(0, 4).map(r => { const e = peopleById[r.employeeId]; return <Box className="late-row" key={r.id}><Avatar className="table-avatar">{e?.name.split(' ').map(n => n[0]).slice(0, 2).join('')}</Avatar><Box flex={1}><Typography variant="body2" fontWeight={650}>{e?.name || 'Employee'}</Typography><Typography variant="caption" color="text.secondary">{e?.department}</Typography></Box><Status value="Absent"/></Box> })}{!stats.todays.some(r => r.status === 'Absent') && <Empty label="No absent employees recorded today"/>}</CardContent></Panel>
      <Panel title="Recent attendance" action={<Button size="small" component={NavLink} to="/attendance">View all</Button>} className="full-panel"><GridTable rows={recent.map(r => ({ ...r, employee: peopleById[r.employeeId]?.name || 'Unknown employee', department: peopleById[r.employeeId]?.department || '—' }))} columns={cols}/></Panel>
      <Panel title="Department summary" action={<Button size="small" component={NavLink} to="/departments">Manage teams</Button>} className="full-panel"><Box className="dept-summary">{deptRows.map(d => <Box className="dept-row" key={d.id}><Box className="dept-initial">{d.name[0]}</Box><Box flex={1}><Box display="flex" justifyContent="space-between"><Typography variant="body2" fontWeight={650}>{d.name}</Typography><Typography variant="body2" fontWeight={700}>{d.percent}%</Typography></Box><LinearProgress variant="determinate" value={d.percent} sx={{ mt: 1, height: 5, borderRadius: 4 }}/></Box><Typography variant="caption" color="text.secondary" width={70} textAlign="right">{d.headcount} people</Typography></Box>)}</Box></Panel>
    </Box>
  </>
}
function weekTrend(records, employees) {
  const active = employees.filter(e => e.status === 'Active').length
  return Array.from({ length: 7 }, (_, ix) => { const d = new Date(); d.setDate(d.getDate() - (6 - ix)); const key = localDate(d); const r = records.filter(x => x.date === key); return { day: d.toLocaleDateString('en-US', { weekday: 'short' }), rate: attendancePercent(r, active) } })
}
function Empty({ label }) { return <Box className="empty-state"><Typography color="text.secondary" variant="body2">{label}</Typography></Box> }

function EmployeesPage() {
  const { employees, setEmployees, departments, records, setRecords, notify } = useStore()
  const [query, setQuery] = useState('')
  const [dept, setDept] = useState('All departments')
  const [status, setStatus] = useState('All attendance')
  const [edit, setEdit] = useState(null)
  const [confirm, setConfirm] = useState(null)
  const navigate = useNavigate()
  const todayStatus = e => statusForToday(e.id, records)
  const rows = employees.filter(e => `${e.name} ${e.id} ${e.email}`.toLowerCase().includes(query.toLowerCase()) && (dept === 'All departments' || e.department === dept) && (status === 'All attendance' || todayStatus(e) === status)).map(e => ({ ...e, todayStatus: todayStatus(e), percent: attendancePercent(recordsFor(records, e.id)) }))
  const columns = [{ field: 'id', headerName: 'EMPLOYEE ID', width: 115 }, { field: 'name', headerName: 'EMPLOYEE', flex: 1.2, minWidth: 165, renderCell: p => <Box className="employee-cell"><Avatar className="table-avatar">{p.value.split(' ').map(n => n[0]).slice(0, 2).join('')}</Avatar><Box><Typography variant="body2" fontWeight={650}>{p.value}</Typography><Typography variant="caption" color="text.secondary" display="block">{p.row.email}</Typography><Typography variant="caption" color="text.secondary">{p.row.phone}</Typography></Box></Box> }, { field: 'department', headerName: 'DEPARTMENT', flex: 1, minWidth: 130 }, { field: 'position', headerName: 'POSITION', flex: 1, minWidth: 125 }, { field: 'percent', headerName: 'ATTENDANCE', width: 115, renderCell: p => <Box width="100%"><Typography variant="caption" fontWeight={650}>{p.value}%</Typography><LinearProgress variant="determinate" value={p.value} sx={{ height: 4, borderRadius: 3 }}/></Box> }, { field: 'todayStatus', headerName: "TODAY'S STATUS", width: 130, renderCell: p => <Status value={p.value}/> }, { field: 'status', headerName: 'STATUS', width: 95, renderCell: p => <Status value={p.value}/> }, { field: 'actions', headerName: '', width: 90, sortable: false, renderCell: p => <Stack direction="row"><Tooltip title="Edit"><IconButton size="small" onClick={e => { e.stopPropagation(); setEdit(p.row) }}><EditRounded fontSize="small"/></IconButton></Tooltip><Tooltip title="Delete"><IconButton size="small" onClick={e => { e.stopPropagation(); setConfirm(p.row) }}><DeleteOutlineRounded fontSize="small"/></IconButton></Tooltip></Stack> }]
  const save = data => { const duplicate = employees.find(e => e.email.toLowerCase() === data.email.toLowerCase() && e.id !== data.id); if (duplicate) return notify('An employee with this email already exists.', 'error'); setEmployees(edit?.id ? employees.map(e => e.id === edit.id ? { ...data, id: edit.id } : e) : [...employees, { ...data, id: `EMP-${Date.now().toString().slice(-6)}` }]); setEdit(null); notify(edit?.id ? 'Employee details updated.' : 'Employee added successfully.') }
  return <><PageHeader eyebrow="PEOPLE DIRECTORY" title="Employees" subtitle="Manage your people, teams, and attendance at a glance." action={<Button variant="contained" startIcon={<AddRounded/>} onClick={() => setEdit({})}>Add employee</Button>}/><Card className="table-card"><Box className="toolbar-filters"><TextField size="small" placeholder="Search employees" value={query} onChange={e => setQuery(e.target.value)} InputProps={{ startAdornment: <InputAdornment position="start"><SearchRounded fontSize="small"/></InputAdornment> }}/><FilterSelect value={dept} onChange={setDept} values={['All departments', ...departments.map(d => d.name)]}/><FilterSelect value={status} onChange={setStatus} values={['All attendance', 'Present', 'Absent', 'Late', 'On Leave', 'Not Marked']}/><Box flex={1}/><Typography variant="caption" color="text.secondary">{rows.length} employees</Typography></Box><GridTable rows={rows} columns={columns} onRowClick={p => navigate(`/employees/${p.row.id}`)}/></Card><EmployeeDialog open={Boolean(edit)} initial={edit} departments={departments} onClose={() => setEdit(null)} onSave={save}/><ConfirmDialog open={Boolean(confirm)} title="Delete employee?" message={`Remove ${confirm?.name} and their attendance history? This cannot be undone.`} onClose={() => setConfirm(null)} onConfirm={() => { setEmployees(employees.filter(e => e.id !== confirm.id)); setRecords(records.filter(r => r.employeeId !== confirm.id)); setConfirm(null); notify('Employee and attendance history deleted.') }}/></>
}
function FilterSelect({ value, onChange, values, minWidth = 150 }) { const options = values.map(item => typeof item === 'string' ? { value: item, label: item } : item); return <FormControl size="small" sx={{ minWidth }}><Select value={value} onChange={e => onChange(e.target.value)}>{options.map(option => <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>)}</Select></FormControl> }
function EmployeeDialog({ open, initial, departments, onClose, onSave }) {
  const empty = { name: '', department: departments[0]?.name || '', position: '', email: '', phone: '', status: 'Active' }
  const [form, setForm] = useState(empty)
  const [error, setError] = useState('')
  useEffect(() => { setForm(initial?.id ? { ...initial } : empty); setError('') }, [initial, open])
  const field = key => e => setForm(prev => ({ ...prev, [key]: e.target.value }))
  return <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm"><DialogTitle>{initial?.id ? 'Edit employee' : 'Add employee'}</DialogTitle><DialogContent><Stack gap={2} mt={1}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Full name" value={form.name} onChange={field('name')} required/><Box className="form-two"><TextField label="Email" type="email" value={form.email} onChange={field('email')} required/><TextField label="Phone" value={form.phone} onChange={field('phone')}/></Box><Box className="form-two"><TextField select label="Department" value={form.department} onChange={field('department')}><MenuItem value="Unassigned">Unassigned</MenuItem>{departments.map(d => <MenuItem key={d.id} value={d.name}>{d.name}</MenuItem>)}</TextField><TextField label="Position" value={form.position} onChange={field('position')} required/></Box><TextField select label="Employment status" value={form.status} onChange={field('status')}><MenuItem value="Active">Active</MenuItem><MenuItem value="Inactive">Inactive</MenuItem></TextField></Stack></DialogContent><DialogActions><Button onClick={onClose}>Cancel</Button><Button variant="contained" onClick={() => { if (!form.name.trim() || !form.email.includes('@') || !form.position.trim()) { setError('Enter a name, valid email, and position.'); return } onSave(form) }}>Save employee</Button></DialogActions></Dialog>
}
function ConfirmDialog({ open, title, message, onClose, onConfirm }) { return <Dialog open={open} onClose={onClose}><DialogTitle>{title}</DialogTitle><DialogContent><Typography color="text.secondary">{message}</Typography></DialogContent><DialogActions><Button onClick={onClose}>Cancel</Button><Button color="error" variant="contained" onClick={onConfirm}>Delete</Button></DialogActions></Dialog> }

function AttendancePage() {
  const { employees, departments, records, setRecords, settings, setSettings, notify } = useStore()
  const [query, setQuery] = useState('')
  const [date, setDate] = useState('')
  const [dept, setDept] = useState('All departments')
  const [status, setStatus] = useState('All statuses')
  const [edit, setEdit] = useState(null)
  const [remove, setRemove] = useState(null)
  const [lateMode, setLateMode] = useState(false)
  const [expected, setExpected] = useState(settings.expectedStart)
  const nameOf = id => employees.find(e => e.id === id)?.name || 'Unknown employee'
  const departmentOf = id => employees.find(e => e.id === id)?.department || '—'
  const data = records.filter(r => (!lateMode || r.status === 'Late') && nameOf(r.employeeId).toLowerCase().includes(query.toLowerCase()) && (!date || r.date === date) && (dept === 'All departments' || departmentOf(r.employeeId) === dept) && (status === 'All statuses' || r.status === status)).sort((a, b) => b.date.localeCompare(a.date))
  const rows = data.map(r => ({ ...r, employee: nameOf(r.employeeId), department: departmentOf(r.employeeId), hours: calculateWorkingHours(r.checkIn, r.checkOut), expectedTime: settings.expectedStart, minutesLate: r.status === 'Late' ? calculateMinutesLate(r.checkIn, settings.expectedStart) : 0 }))
  const columns = [{ field: 'id', headerName: 'RECORD ID', width: 185 }, { field: 'date', headerName: 'DATE', width: 118, valueFormatter: value => prettyDate(value) }, { field: 'employee', headerName: 'EMPLOYEE', flex: 1, minWidth: 150 }, { field: 'department', headerName: 'DEPARTMENT', flex: .9, minWidth: 135 }, ...(lateMode ? [{ field: 'expectedTime', headerName: 'EXPECTED', width: 95 }, { field: 'minutesLate', headerName: 'MINUTES LATE', width: 110 }] : []), { field: 'checkIn', headerName: 'CHECK IN', width: 95, renderCell: p => p.value || '—' }, { field: 'checkOut', headerName: 'CHECK OUT', width: 100, renderCell: p => p.value || '—' }, { field: 'hours', headerName: 'HOURS', width: 80, valueFormatter: value => value ? `${value}h` : '—' }, { field: 'status', headerName: 'STATUS', width: 110, renderCell: p => <Status value={p.value}/> }, { field: 'remarks', headerName: 'REMARKS', flex: .8, minWidth: 120 }, { field: 'actions', headerName: '', width: 90, sortable: false, renderCell: p => <Stack direction="row"><IconButton size="small" onClick={() => setEdit(p.row)}><EditRounded fontSize="small"/></IconButton><IconButton size="small" onClick={() => setRemove(p.row)}><DeleteOutlineRounded fontSize="small"/></IconButton></Stack> }]
  const save = form => {
    const duplicate = records.find(r => r.employeeId === form.employeeId && r.date === form.date && r.id !== form.id)
    if (duplicate) return notify('This employee already has an attendance record for that date.', 'error')
    const calculated = { ...form, status: ['Absent', 'On Leave'].includes(form.status) ? form.status : (form.checkIn && calculateMinutesLate(form.checkIn, expected) > 0 ? 'Late' : form.status === 'Late' ? 'Present' : form.status) }
    setRecords(edit?.id ? records.map(r => r.id === edit.id ? calculated : r) : [{ ...calculated, id: `ATT-${Date.now()}` }, ...records])
    if (calculated.status === 'Late') notify(`Late arrival: ${calculateMinutesLate(form.checkIn, expected)} minutes after start.`, 'warning')
    else notify(edit?.id ? 'Attendance record updated.' : 'Attendance recorded.')
    setEdit(null)
  }
  return <><PageHeader eyebrow="TIME & ATTENDANCE" title={lateMode ? 'Late arrivals' : 'Attendance records'} subtitle={lateMode ? 'Review late check-ins and follow up with your team.' : 'Review and manage daily attendance across your organization.'} action={<Button variant="contained" startIcon={<AddRounded/>} onClick={() => setEdit({})}>Record attendance</Button>}/><Card className="table-card"><Tabs value={lateMode ? 1 : 0} onChange={(_, v) => setLateMode(Boolean(v))} className="page-tabs"><Tab label="All records"/><Tab icon={<AccessTimeRounded fontSize="small"/>} iconPosition="start" label="Late arrivals"/></Tabs><Box className="toolbar-filters"><TextField size="small" placeholder="Search employee" value={query} onChange={e => setQuery(e.target.value)} InputProps={{ startAdornment: <InputAdornment position="start"><SearchRounded fontSize="small"/></InputAdornment> }}/><TextField size="small" type="date" value={date} onChange={e => setDate(e.target.value)} InputLabelProps={{ shrink: true }} label="Date"/><FilterSelect value={dept} onChange={setDept} values={['All departments', ...departments.map(d => d.name)]}/><FilterSelect value={status} onChange={setStatus} values={['All statuses', 'Present', 'Late', 'Absent', 'On Leave']}/><Box flex={1}/><Tooltip title="Set expected start time"><TextField size="small" type="time" label="Start time" value={expected} onChange={e => { setExpected(e.target.value); setSettings({ ...settings, expectedStart: e.target.value }) }} InputLabelProps={{ shrink: true }} sx={{ width: 135 }}/></Tooltip><Typography variant="caption" color="text.secondary">{rows.length} records</Typography></Box>{lateMode && <Alert severity="warning" sx={{ mx: 2, mb: 1 }}>Late minutes are calculated using the expected start time of {expected}.</Alert>}<GridTable rows={rows} columns={columns}/></Card><AttendanceDialog open={Boolean(edit)} initial={edit} employees={employees} settings={settings} onClose={() => setEdit(null)} onSave={save}/><ConfirmDialog open={Boolean(remove)} title="Delete attendance record?" message={`${nameOf(remove?.employeeId)} · ${prettyDate(remove?.date)}`} onClose={() => setRemove(null)} onConfirm={() => { setRecords(records.filter(r => r.id !== remove.id)); setRemove(null); notify('Attendance record deleted.') }}/></>
}
function AttendanceDialog({ open, initial, employees, settings, onClose, onSave }) {
  const [form, setForm] = useState({ employeeId: '', date: today, checkIn: '', checkOut: '', status: 'Present', remarks: '' })
  const [error, setError] = useState('')
  useEffect(() => { setForm(initial?.id ? { ...initial } : { employeeId: employees[0]?.id || '', date: today, checkIn: '', checkOut: '', status: 'Present', remarks: '' }); setError('') }, [initial, open, employees])
  const field = key => e => setForm(prev => ({ ...prev, [key]: e.target.value }))
  const late = form.checkIn && calculateMinutesLate(form.checkIn, settings.expectedStart)
  return <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm"><DialogTitle>{initial?.id ? 'Edit attendance' : 'Record attendance'}</DialogTitle><DialogContent><Stack gap={2} mt={1}>{error && <Alert severity="error">{error}</Alert>}<TextField select label="Employee" value={form.employeeId} onChange={field('employeeId')} required>{employees.map(e => <MenuItem key={e.id} value={e.id}>{e.name} · {e.department}</MenuItem>)}</TextField><TextField type="date" label="Date" value={form.date} onChange={field('date')} InputLabelProps={{ shrink: true }} required/><Box className="form-two"><TextField type="time" label="Check-in time" value={form.checkIn} onChange={field('checkIn')} InputLabelProps={{ shrink: true }}/><TextField type="time" label="Check-out time" value={form.checkOut} onChange={field('checkOut')} InputLabelProps={{ shrink: true }}/></Box><TextField select label="Status" value={late ? 'Late' : form.status} onChange={field('status')}>{['Present', 'Late', 'Absent', 'On Leave'].map(s => <MenuItem key={s} value={s}>{s}</MenuItem>)}</TextField>{late > 0 && <Alert severity="warning">This check-in is {late} minutes late based on {settings.expectedStart}.</Alert>}<TextField label="Remarks" value={form.remarks} onChange={field('remarks')} multiline minRows={2}/>{form.checkIn && form.checkOut && <Typography variant="caption" color="text.secondary">Calculated working time: {calculateWorkingHours(form.checkIn, form.checkOut)} hours</Typography>}</Stack></DialogContent><DialogActions><Button onClick={onClose}>Cancel</Button><Button variant="contained" onClick={() => { if (!form.employeeId || !form.date) { setError('Select an employee and date.'); return } if ((form.status === 'Late' || late > 0) && !form.checkIn) { setError('A check-in time is required for a late attendance record.'); return } if (form.checkIn && form.checkOut && form.checkOut === form.checkIn) { setError('Check-out must be different from check-in.'); return } onSave(form) }}>Save record</Button></DialogActions></Dialog>
}

function EmployeeDetails() {
  const { employeeId } = useParams()
  const { employees, records, settings } = useStore()
  const employee = employees.find(e => e.id === employeeId)
  const month = today.slice(0, 7)
  const mine = recordsFor(records, employeeId)
  const thisMonth = recordsFor(records, employeeId, month)
  const summary = summarize(thisMonth)
  if (!employee) return <><Button startIcon={<ArrowBackRounded/>} component={NavLink} to="/employees">Employees</Button><Empty label="Employee not found"/></>
  const history = [...mine].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 12)
  const trend = Array.from({ length: 6 }, (_, i) => { const d = new Date(); d.setMonth(d.getMonth() - 5 + i); const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`; return { month: d.toLocaleDateString('en-US', { month: 'short' }), attendance: attendancePercent(recordsFor(records, employeeId, key), monthWeekdays(key)) } })
  return <><Button startIcon={<ArrowBackRounded/>} component={NavLink} to="/employees" className="back-link">All employees</Button><PageHeader eyebrow={`${employee.id} · ${employee.department.toUpperCase()}`} title={employee.name} subtitle={`${employee.position} · ${employee.email} · ${employee.phone}`} action={<Status value={statusForToday(employee.id, records)}/>}/><Box className="stats-grid detail-stats"><StatCard title="Monthly attendance" value={`${attendancePercent(thisMonth, monthWeekdays(month))}%`} note={monthLabel(month)} Icon={EventAvailableRounded} progress={attendancePercent(thisMonth, monthWeekdays(month))}/><StatCard title="Present days" value={summary.Present || 0} note="This month" Icon={GroupsRounded} color="#468e71"/><StatCard title="Late days" value={summary.Late || 0} note={`Expected start ${settings.expectedStart}`} Icon={AccessTimeRounded} color="#d58a35"/><StatCard title="Absent / leave" value={`${summary.Absent || 0} / ${summary['On Leave'] || 0}`} note="This month" Icon={CalendarMonthRounded} color="#7186bb"/></Box><Box className="detail-grid"><Panel title="Attendance history" className="full-panel"><GridTable rows={history.map(r => ({ ...r, hours: calculateWorkingHours(r.checkIn, r.checkOut) }))} columns={[{ field: 'date', headerName: 'DATE', width: 145, valueFormatter: value => prettyDate(value) }, { field: 'checkIn', headerName: 'CHECK IN', width: 115, renderCell: p => p.value || '—' }, { field: 'checkOut', headerName: 'CHECK OUT', width: 115, renderCell: p => p.value || '—' }, { field: 'hours', headerName: 'HOURS', width: 90, valueFormatter: value => value ? `${value}h` : '—' }, { field: 'status', headerName: 'STATUS', width: 120, renderCell: p => <Status value={p.value}/> }, { field: 'remarks', headerName: 'REMARKS', flex: 1, minWidth: 150 }]}/></Panel><Panel title="Monthly statistics" className="detail-chart"><CardContent sx={{ height: 245 }}><ResponsiveContainer><LineChart data={trend} margin={{ top: 16, right: 15, left: -22, bottom: 0 }}><CartesianGrid stroke="#edf0ee"/><XAxis dataKey="month" axisLine={false} tickLine={false}/><YAxis domain={[0, 100]} axisLine={false} tickLine={false} tickFormatter={v => `${v}%`}/><ChartTooltip formatter={v => [`${v}%`, 'Attendance']}/><Line dataKey="attendance" type="monotone" stroke="#4b9478" strokeWidth={3} dot={{ r: 3 }}/></LineChart></ResponsiveContainer></CardContent></Panel></Box></>
}

function CalendarPage() {
  const { employees, departments, records } = useStore()
  const [cursor, setCursor] = useState(() => new Date())
  const [employeeId, setEmployeeId] = useState('All employees')
  const [department, setDepartment] = useState('All departments')
  const [selected, setSelected] = useState(today)
  const [detail, setDetail] = useState(null)
  const year = cursor.getFullYear(), month = cursor.getMonth()
  const first = new Date(year, month, 1).getDay()
  const days = new Date(year, month + 1, 0).getDate()
  const expectedEmployees = employees.filter(e => e.status === 'Active' && (employeeId === 'All employees' || e.id === employeeId) && (department === 'All departments' || e.department === department))
  const visible = records.filter(r => (employeeId === 'All employees' || r.employeeId === employeeId) && (department === 'All departments' || employees.find(e => e.id === r.employeeId)?.department === department))
  const listForDay = date => visible.filter(r => r.date === date)
  const selectedRecords = listForDay(selected)
  return <><PageHeader eyebrow="ATTENDANCE PLANNER" title="Attendance calendar" subtitle="Explore check-ins and attendance patterns by day."/><Card className="calendar-card"><Box className="toolbar-filters"><FilterSelect value={employeeId} onChange={setEmployeeId} values={['All employees', ...employees.map(e => ({ value: e.id, label: e.name }))]} minWidth={190}/><FilterSelect value={department} onChange={setDepartment} values={['All departments', ...departments.map(d => d.name)]} minWidth={180}/><Box flex={1}/><IconButton onClick={() => setCursor(new Date(year, month - 1, 1))}><ArrowBackRounded/></IconButton><Typography fontWeight={700} minWidth={145} textAlign="center">{cursor.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</Typography><IconButton onClick={() => setCursor(new Date(year, month + 1, 1))}><ArrowForwardRounded/></IconButton></Box><Box className="calendar-layout"><Box className="calendar-main"><Box className="calendar-grid weekday-row">{['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(x => <Typography key={x} variant="caption">{x}</Typography>)}</Box><Box className="calendar-grid">{Array.from({ length: first }, (_, i) => <Box key={`empty-${i}`} className="calendar-day empty-day"/>)}{Array.from({ length: days }, (_, i) => { const n = i + 1, date = `${year}-${String(month + 1).padStart(2, '0')}-${String(n).padStart(2, '0')}`; const list = listForDay(date); const tally = summarize(list); const isPastWeekday = date <= today && ![0, 6].includes(new Date(`${date}T12:00:00`).getDay()); const unmarked = isPastWeekday ? Math.max(0, expectedEmployees.length - list.length) : 0; return <Box key={date} role="button" tabIndex={0} onClick={() => setSelected(date)} onDoubleClick={() => setDetail(list[0] || { date })} className={`calendar-day ${selected === date ? 'selected-day' : ''} ${date === today ? 'current-day' : ''}`}><Typography variant="body2" fontWeight={date === today ? 700 : 500}>{n}</Typography><Box className="calendar-indicators">{['Present', 'Late', 'Absent', 'On Leave'].map(s => tally[s] ? <Tooltip key={s} title={`${tally[s]} ${s}`}><span className={`cal-dot ${s.toLowerCase().replace(' ', '-')}`}/></Tooltip> : null)}{unmarked > 0 && <Tooltip title={`${unmarked} not marked`}><span className="cal-dot not-marked"/></Tooltip>}</Box><Typography variant="caption" color="text.secondary">{list.length || (isPastWeekday ? 'Not marked' : '')}</Typography></Box> })}</Box><Box className="calendar-legend">{['Present', 'Late', 'Absent', 'On Leave', 'Not Marked'].map(s => <Box key={s}><i className={`cal-dot ${s.toLowerCase().replace(' ', '-')}`}/>{s}</Box>)}</Box></Box><Box className="selected-day-panel"><Typography className="eyebrow">SELECTED DAY</Typography><Typography variant="h6">{prettyDate(selected)}</Typography><Divider sx={{ my: 1.5 }}/>{selectedRecords.length ? <Stack gap={1}>{selectedRecords.slice(0, 12).map(r => { const e = employees.find(x => x.id === r.employeeId); return <Box className="calendar-record" key={r.id} onClick={() => setDetail(r)}><Avatar className="table-avatar">{e?.name.split(' ').map(x => x[0]).slice(0, 2).join('')}</Avatar><Box flex={1}><Typography variant="body2" fontWeight={650}>{e?.name || 'Unknown'}</Typography><Typography variant="caption" color="text.secondary">{r.checkIn || r.checkOut ? `${r.checkIn || '—'} – ${r.checkOut || '—'}` : r.status}</Typography></Box><Status value={r.status}/></Box>})}</Stack> : <Empty label="No attendance records for this date"/>}</Box></Box></Card><Dialog open={Boolean(detail)} onClose={() => setDetail(null)}><DialogTitle>Attendance details</DialogTitle><DialogContent>{detail?.id ? <Stack gap={1}><Typography><b>Employee:</b> {employees.find(e => e.id === detail.employeeId)?.name}</Typography><Typography><b>Date:</b> {prettyDate(detail.date)}</Typography><Typography><b>Check-in:</b> {detail.checkIn || '—'}</Typography><Typography><b>Check-out:</b> {detail.checkOut || '—'}</Typography><Typography><b>Status:</b> {detail.status}</Typography></Stack> : <Typography>No record on {prettyDate(detail?.date)}.</Typography>}</DialogContent><DialogActions><Button onClick={() => setDetail(null)}>Close</Button></DialogActions></Dialog></>
}

function MonthlyPage() {
  const { employees, departments, records } = useStore()
  const [month, setMonth] = useState(today.slice(0, 7))
  const [dept, setDept] = useState('All departments')
  const [person, setPerson] = useState('All employees')
  const active = employees.filter(e => e.status === 'Active' && (dept === 'All departments' || e.department === dept) && (person === 'All employees' || e.id === person))
  const weekdays = monthWeekdays(month)
  const rows = active.map(e => { const data = recordsFor(records, e.id, month); const s = summarize(data); const per = attendancePercent(data, weekdays); return { id: e.id, employee: e.name, department: e.department, workingDays: weekdays, present: s.Present || 0, absent: s.Absent || 0, late: s.Late || 0, leave: s['On Leave'] || 0, percent: per } })
  return <><PageHeader eyebrow="PEOPLE ANALYTICS" title="Monthly attendance" subtitle="A clear picture of attendance across your teams." action={<Button variant="outlined" startIcon={<DownloadRounded/>} onClick={() => downloadCsv('monthly-attendance.csv', rows)}>Export CSV</Button>}/><Card className="table-card"><Box className="toolbar-filters"><TextField type="month" size="small" label="Report month" value={month} onChange={e => setMonth(e.target.value)} InputLabelProps={{ shrink: true }}/><FilterSelect value={dept} onChange={setDept} values={['All departments', ...departments.map(d => d.name)]}/><FilterSelect value={person} onChange={setPerson} values={['All employees', ...employees.map(e => ({ value: e.id, label: e.name }))]} minWidth={190}/><Box flex={1}/><Typography variant="caption" color="text.secondary">{weekdays} expected weekdays · {monthLabel(month)}</Typography></Box><GridTable rows={rows} columns={[{ field: 'employee', headerName: 'EMPLOYEE', flex: 1, minWidth: 170 }, { field: 'department', headerName: 'DEPARTMENT', flex: 1, minWidth: 145 }, { field: 'workingDays', headerName: 'WORKING DAYS', width: 125 }, { field: 'present', headerName: 'PRESENT', width: 95 }, { field: 'absent', headerName: 'ABSENT', width: 90 }, { field: 'late', headerName: 'LATE', width: 80 }, { field: 'leave', headerName: 'LEAVE', width: 80 }, { field: 'percent', headerName: 'ATTENDANCE', width: 125, renderCell: p => <Box width="100%"><Typography variant="caption" fontWeight={650}>{p.value}%</Typography><LinearProgress variant="determinate" value={p.value} sx={{ height: 4, borderRadius: 3 }}/></Box> }]}/></Card><Box mt={2}><Alert severity="info">Attendance percentage is calculated as present days divided by the month’s expected weekdays ({weekdays}).</Alert></Box></>
}

function DepartmentsPage() {
  const { employees, setEmployees, departments, setDepartments, records, notify } = useStore()
  const [search, setSearch] = useState('')
  const [edit, setEdit] = useState(null)
  const [remove, setRemove] = useState(null)
  const rows = departments.filter(d => d.name.toLowerCase().includes(search.toLowerCase())).map(d => {
    const team = employees.filter(e => e.department === d.name && e.status === 'Active')
    const statuses = team.map(e => statusForToday(e.id, records))
    return { ...d, headcount: team.length, present: statuses.filter(s => s === 'Present').length, absent: statuses.filter(s => s === 'Absent').length, late: statuses.filter(s => s === 'Late').length, percent: attendancePercent(records.filter(r => r.date === today && team.some(e => e.id === r.employeeId)), team.length) }
  })
  const columns = [{ field: 'id', headerName: 'DEPARTMENT ID', width: 145 }, { field: 'name', headerName: 'DEPARTMENT', flex: 1, minWidth: 190, renderCell: p => <Box display="flex" gap={1.2} alignItems="center"><Box className="dept-initial">{p.value[0]}</Box><Typography variant="body2" fontWeight={650}>{p.value}</Typography></Box> }, { field: 'headcount', headerName: 'EMPLOYEES', width: 110 }, { field: 'present', headerName: 'PRESENT', width: 95 }, { field: 'absent', headerName: 'ABSENT', width: 90 }, { field: 'late', headerName: 'LATE', width: 80 }, { field: 'percent', headerName: 'ATTENDANCE', width: 125, renderCell: p => <Typography fontWeight={650} variant="body2">{p.value}%</Typography> }, { field: 'actions', headerName: '', width: 95, sortable: false, renderCell: p => <><IconButton size="small" onClick={() => setEdit(p.row)}><EditRounded fontSize="small"/></IconButton><IconButton size="small" onClick={() => setRemove(p.row)}><DeleteOutlineRounded fontSize="small"/></IconButton></> }]
  const save = form => { if (departments.some(d => d.name.toLowerCase() === form.name.trim().toLowerCase() && d.id !== form.id)) return notify('That department already exists.', 'error'); if (edit?.id) { const old = edit.name; setDepartments(departments.map(d => d.id === edit.id ? { ...d, name: form.name.trim() } : d)); if (old !== form.name.trim()) setEmployees(employees.map(e => e.department === old ? { ...e, department: form.name.trim() } : e)) } else setDepartments([...departments, { id: `DEP-${Date.now().toString().slice(-6)}`, name: form.name.trim() }]); setEdit(null); notify('Department saved.') }
  return <><PageHeader eyebrow="ORGANIZATION" title="Departments" subtitle="Monitor team size and attendance across your organization." action={<Button variant="contained" startIcon={<AddRounded/>} onClick={() => setEdit({})}>Add department</Button>}/><Card className="table-card"><Box className="toolbar-filters"><TextField size="small" placeholder="Search departments" value={search} onChange={e => setSearch(e.target.value)} InputProps={{ startAdornment: <InputAdornment position="start"><SearchRounded fontSize="small"/></InputAdornment> }}/><Box flex={1}/><Typography variant="caption" color="text.secondary">{rows.length} departments</Typography></Box><GridTable rows={rows} columns={columns}/></Card><DepartmentDialog open={Boolean(edit)} initial={edit} onClose={() => setEdit(null)} onSave={save}/><ConfirmDialog open={Boolean(remove)} title="Delete department?" message={employees.some(e => e.department === remove?.name) ? `Employees in ${remove?.name} will be moved to Unassigned.` : `Delete ${remove?.name}?`} onClose={() => setRemove(null)} onConfirm={() => { setEmployees(employees.map(e => e.department === remove.name ? { ...e, department: 'Unassigned' } : e)); setDepartments(departments.filter(d => d.id !== remove.id)); setRemove(null); notify('Department deleted. Employees were moved to Unassigned.') }}/></>
}
function DepartmentDialog({ open, initial, onClose, onSave }) { const [name, setName] = useState(''); const [error, setError] = useState(''); useEffect(() => { setName(initial?.name || ''); setError('') }, [initial, open]); return <Dialog open={open} onClose={onClose} fullWidth maxWidth="xs"><DialogTitle>{initial?.id ? 'Edit department' : 'Add department'}</DialogTitle><DialogContent>{error && <Alert severity="error">{error}</Alert>}<TextField autoFocus fullWidth label="Department name" value={name} onChange={e => setName(e.target.value)} sx={{ mt: 1 }}/></DialogContent><DialogActions><Button onClick={onClose}>Cancel</Button><Button variant="contained" onClick={() => { if (!name.trim()) { setError('Enter a department name.'); return } onSave({ id: initial?.id, name }) }}>Save</Button></DialogActions></Dialog> }

function ReportsPage() {
  const { employees, departments, records, settings } = useStore()
  const [tab, setTab] = useState(0)
  const [start, setStart] = useState('')
  const [end, setEnd] = useState('')
  const [month, setMonth] = useState(today.slice(0, 7))
  const [dept, setDept] = useState('All departments')
  const [person, setPerson] = useState('All employees')
  const [status, setStatus] = useState('All statuses')
  const nameOf = id => employees.find(e => e.id === id)?.name || 'Unknown employee'
  const departmentOf = id => employees.find(e => e.id === id)?.department || '—'
  const filtered = records.filter(r => (tab !== 0 || start || end ? true : r.date === today) && (!start || r.date >= start) && (!end || r.date <= end) && (!month || monthKey(r.date) === month) && (dept === 'All departments' || departmentOf(r.employeeId) === dept) && (person === 'All employees' || r.employeeId === person) && (status === 'All statuses' || r.status === status))
  const typeMap = ['Daily attendance report', 'Monthly attendance report', 'Employee attendance report', 'Department attendance report', 'Late attendance report', 'Absence report']
  const filteredByTab = filtered.filter(r => tab === 4 ? r.status === 'Late' : tab === 5 ? r.status === 'Absent' : true)
  const attendanceRows = filteredByTab.map(r => ({ date: r.date, employee: nameOf(r.employeeId), department: departmentOf(r.employeeId), checkIn: r.checkIn || '—', checkOut: r.checkOut || '—', hours: calculateWorkingHours(r.checkIn, r.checkOut) || '—', status: r.status, minutesLate: r.status === 'Late' ? calculateMinutesLate(r.checkIn, settings.expectedStart) : 0, remarks: r.remarks }))
  const rows = tab === 1
    ? employees.filter(e => e.status === 'Active' && (dept === 'All departments' || e.department === dept) && (person === 'All employees' || e.id === person)).map(e => { const items = filteredByTab.filter(r => r.employeeId === e.id); const counts = summarize(items); return { employee: e.name, department: e.department, workingDays: monthWeekdays(month), present: counts.Present || 0, absent: counts.Absent || 0, late: counts.Late || 0, leave: counts['On Leave'] || 0, percentage: attendancePercent(items, monthWeekdays(month)) } })
    : tab === 3
      ? departments.filter(d => dept === 'All departments' || d.name === dept).map(d => { const members = employees.filter(e => e.department === d.name && e.status === 'Active'); const items = filteredByTab.filter(r => departmentOf(r.employeeId) === d.name); const counts = summarize(items); return { department: d.name, employees: members.length, present: counts.Present || 0, absent: counts.Absent || 0, late: counts.Late || 0, leave: counts['On Leave'] || 0, percentage: attendancePercent(items, monthWeekdays(month) * Math.max(1, members.length)) } })
      : attendanceRows
  const reportColumns = tab === 1
    ? [{ field: 'employee', headerName: 'EMPLOYEE', flex: 1, minWidth: 150 }, { field: 'department', headerName: 'DEPARTMENT', flex: 1, minWidth: 140 }, { field: 'workingDays', headerName: 'WORKING DAYS', width: 120 }, { field: 'present', headerName: 'PRESENT', width: 90 }, { field: 'absent', headerName: 'ABSENT', width: 90 }, { field: 'late', headerName: 'LATE', width: 80 }, { field: 'leave', headerName: 'LEAVE', width: 80 }, { field: 'percentage', headerName: 'ATTENDANCE', width: 115, valueFormatter: value => `${value}%` }]
    : tab === 3
      ? [{ field: 'department', headerName: 'DEPARTMENT', flex: 1, minWidth: 165 }, { field: 'employees', headerName: 'EMPLOYEES', width: 100 }, { field: 'present', headerName: 'PRESENT', width: 90 }, { field: 'absent', headerName: 'ABSENT', width: 90 }, { field: 'late', headerName: 'LATE', width: 80 }, { field: 'leave', headerName: 'LEAVE', width: 80 }, { field: 'percentage', headerName: 'ATTENDANCE', width: 120, valueFormatter: value => `${value}%` }]
      : [{ field: 'date', headerName: 'DATE', width: 125, valueFormatter: value => prettyDate(value) }, { field: 'employee', headerName: 'EMPLOYEE', flex: 1, minWidth: 150 }, { field: 'department', headerName: 'DEPARTMENT', flex: 1, minWidth: 140 }, { field: 'checkIn', headerName: 'CHECK IN', width: 100 }, { field: 'checkOut', headerName: 'CHECK OUT', width: 100 }, { field: 'hours', headerName: 'HOURS', width: 85 }, { field: 'status', headerName: 'STATUS', width: 115, renderCell: p => <Status value={p.value}/> }, ...(tab === 4 ? [{ field: 'minutesLate', headerName: 'MINUTES LATE', width: 120 }] : []), { field: 'remarks', headerName: 'REMARKS', flex: 1, minWidth: 120 }]
  return <><PageHeader eyebrow="INSIGHTS & EXPORTS" title="Reports" subtitle="Build a focused attendance report, then export or print it." action={<Stack direction="row" gap={1}><Button variant="outlined" startIcon={<PrintRounded/>} onClick={() => window.print()}>Print</Button><Button variant="contained" startIcon={<DownloadRounded/>} onClick={() => downloadCsv(`cielo-${typeMap[tab].toLowerCase().replaceAll(' ', '-')}.csv`, rows)}>Export CSV</Button></Stack>}/><Card className="table-card"><Tabs value={tab} onChange={(_, v) => setTab(v)} variant="scrollable" scrollButtons="auto" className="page-tabs">{typeMap.map(name => <Tab key={name} label={name.replace(' report', '')}/>)}</Tabs><Box className="toolbar-filters report-filters"><TextField type="date" size="small" label="From" value={start} onChange={e => setStart(e.target.value)} InputLabelProps={{ shrink: true }}/><TextField type="date" size="small" label="To" value={end} onChange={e => setEnd(e.target.value)} InputLabelProps={{ shrink: true }}/><TextField type="month" size="small" label="Month" value={month} onChange={e => setMonth(e.target.value)} InputLabelProps={{ shrink: true }}/><FilterSelect value={dept} onChange={setDept} values={['All departments', ...departments.map(d => d.name)]}/><FilterSelect value={person} onChange={setPerson} values={['All employees', ...employees.map(e => ({ value: e.id, label: e.name }))]} minWidth={175}/><FilterSelect value={status} onChange={setStatus} values={['All statuses', 'Present', 'Late', 'Absent', 'On Leave']} minWidth={135}/></Box><Alert severity="info" sx={{ mx: 2, mb: 1 }}>{typeMap[tab]} · {rows.length} rows · Late after {settings.expectedStart}</Alert><GridTable rows={rows.map((r, i) => ({ ...r, id: r.id || r.employee || r.department || `${r.date}-${i}` }))} columns={reportColumns}/></Card><Box mt={2}><Button component={NavLink} to="/monthly" variant="text" endIcon={<ArrowForwardRounded/>}>Open monthly attendance report</Button></Box></>
}

export default App
